import { DashboardData, Quote, UserProfile, CompanyInfo } from '@/src/types';

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || '/api';

async function fetchJson<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${endpoint}`, {
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
    ...options,
  });

  if (!res.ok) {
    throw new Error(`API error: ${res.status} ${res.statusText}`);
  }

  return res.json();
}

export const api = {
  getDashboardData: async (): Promise<DashboardData> => {
    return fetchJson<DashboardData>('/dashboard');
  },

  getRecentQuotes: async (limit: number = 10): Promise<Quote[]> => {
    return fetchJson<Quote[]>(`/quotes?limit=${limit}`);
  },

  getCurrentUser: async (): Promise<UserProfile> => {
    return fetchJson<UserProfile>('/auth/me');
  },

  getCompanyInfo: async (): Promise<CompanyInfo> => {
    return fetchJson<CompanyInfo>('/company');
  },
};
